package di

import (
	"bytes"
	"errors"
	"fmt"
	"go/format"
	"go/token"
	"go/types"
	"path"
	"path/filepath"
	"sort"
	"strconv"
	"strings"
)

// GeneratedHeader is the first line of every file generated by knit
// (docs/04_guidelines.md §4).
const GeneratedHeader = "// Code generated by knit. DO NOT EDIT."

// ErrGenerate is returned when code cannot be generated for an injector.
var ErrGenerate = errors.New("code generation failed")

// GenerateFile renders the generated source (knit_gen.go / wire_gen.go) for
// injectors that all belong to the same package. The file is guarded by the
// negation of mode's inject tag (the zero Mode means KnitMode).
//
// The output is deterministic: injectors are emitted grouped by source file
// and sorted by name, imports are sorted and aliased with numeric suffixes on
// collision (config, config1, ...), and local variables are numbered v1, v2,
// ... in dependency order with their cleanups named cleanupV1, cleanupV2, ... When a provider fails, the cleanup functions of
// the providers that already succeeded run in LIFO order.
func GenerateFile(mode Mode, injs []*ResolvedInjector) ([]byte, error) {
	mode = mode.orDefault()
	if len(injs) == 0 {
		return nil, fmt.Errorf("%w: no injectors", ErrGenerate)
	}
	for _, r := range injs {
		if r.Injector == nil || r.Injector.Func == nil || r.Injector.Func.Pkg() == nil {
			return nil, fmt.Errorf("%w: injector is missing type information (load it with Loader)", ErrGenerate)
		}
	}
	target := injs[0].Injector.Func.Pkg()
	for _, r := range injs[1:] {
		if p := r.Injector.Func.Pkg().Path(); p != target.Path() {
			return nil, fmt.Errorf("%w: injectors %s and %s are in different packages (%s, %s)",
				ErrGenerate, injs[0].Injector.FuncName, r.Injector.FuncName, target.Path(), p)
		}
	}

	sorted := append([]*ResolvedInjector(nil), injs...)
	sort.Slice(sorted, func(i, j int) bool {
		fi, fj := filepath.Base(sorted[i].Injector.FilePath), filepath.Base(sorted[j].Injector.FilePath)
		if fi != fj {
			return fi < fj
		}
		return sorted[i].Injector.FuncName < sorted[j].Injector.FuncName
	})

	g := newFileGen(target)
	plans := make([]*funcPlan, len(sorted))
	for i, r := range sorted {
		plans[i] = g.plan(r)
	}
	g.assignImports()

	var b bytes.Buffer
	b.WriteString(GeneratedHeader + "\n\n//go:build !" + mode.InjectTag + "\n\npackage " + target.Name() + "\n\n")
	g.writeImports(&b)
	lastFile := ""
	for _, p := range plans {
		if f := filepath.Base(p.r.Injector.FilePath); f != lastFile {
			fmt.Fprintf(&b, "// Injectors from %s:\n\n", f)
			lastFile = f
		}
		g.writeFunc(&b, p)
	}

	src, err := format.Source(b.Bytes())
	if err != nil {
		return nil, fmt.Errorf("%w: formatting generated code for package %s: %w\n%s", ErrGenerate, target.Path(), err, b.Bytes())
	}
	return src, nil
}

// fileGen holds the file-wide naming state.
type fileGen struct {
	target *types.Package
	// pkgScope holds identifiers that neither locals nor imports may shadow:
	// the target package's declarations, predeclared identifiers and keywords.
	pkgScope map[string]bool
	// locals is the union of local identifiers of every generated function;
	// import names must not collide with them.
	locals map[string]bool
	// pkgNames maps every referenced import path to its package name.
	pkgNames map[string]string
	// imports maps import path to the identifier used in the file.
	imports map[string]string
}

func newFileGen(target *types.Package) *fileGen {
	g := &fileGen{
		target:   target,
		pkgScope: make(map[string]bool),
		locals:   make(map[string]bool),
		pkgNames: make(map[string]string),
		imports:  make(map[string]string),
	}
	for _, n := range target.Scope().Names() {
		g.pkgScope[n] = true
	}
	for _, n := range types.Universe.Names() {
		g.pkgScope[n] = true
	}
	return g
}

// funcPlan is the naming plan of one injector function.
type funcPlan struct {
	r          *ResolvedInjector
	params     []string // local name per injector parameter
	vars       []string // result variable per step
	cleanups   []string // cleanup variable per step ("" when the step has none)
	errVar     string
	cleanupFn  string // the aggregated cleanup closure
	cleanupArr string // the []func() slice backing cleanupFn
	useCleanup bool   // whether the cleanup machinery is emitted
}

// plan allocates local names for r and records the packages it references.
func (g *fileGen) plan(r *ResolvedInjector) *funcPlan {
	inj := r.Injector
	n := newNamer(g.pkgScope)
	p := &funcPlan{
		r:        r,
		params:   make([]string, len(inj.Params)),
		vars:     make([]string, len(r.Steps)),
		cleanups: make([]string, len(r.Steps)),
	}

	sig := inj.Func.Signature()
	for i := range sig.Params().Len() {
		name := sig.Params().At(i).Name()
		if name == "" || name == "_" {
			name = "arg"
		}
		p.params[i] = n.take(name)
		g.useType(sig.Params().At(i).Type())
	}
	g.useType(sig.Results().At(0).Type())

	for i := range r.Steps {
		if r.Steps[i].Provider.HasCleanup {
			p.useCleanup = true
		}
	}
	p.useCleanup = p.useCleanup && inj.HasCleanup
	if inj.HasError {
		p.errVar = n.take("err")
	}
	if p.useCleanup {
		p.cleanupArr = n.take("cleanups")
		p.cleanupFn = n.take("cleanup")
	}
	for i := range r.Steps {
		s := &r.Steps[i]
		p.vars[i] = n.seq("v")
		if s.Provider.HasCleanup {
			p.cleanups[i] = n.take("cleanupV" + strings.TrimPrefix(p.vars[i], "v"))
		}
		if s.Provider.PkgPath != g.target.Path() {
			g.pkgNames[s.Provider.PkgPath] = s.Provider.PkgName
		}
	}
	for name := range n.used {
		g.locals[name] = true
	}
	return p
}

// useType records every package referenced by t.
func (g *fileGen) useType(t types.Type) {
	types.TypeString(t, func(p *types.Package) string {
		if p.Path() != g.target.Path() {
			g.pkgNames[p.Path()] = p.Name()
		}
		return p.Name()
	})
}

// assignImports picks a unique identifier per import path, in path order.
func (g *fileGen) assignImports() {
	paths := make([]string, 0, len(g.pkgNames))
	for p := range g.pkgNames {
		paths = append(paths, p)
	}
	sort.Strings(paths)
	taken := make(map[string]bool, len(paths))
	free := func(name string) bool { return !taken[name] && !g.pkgScope[name] && !g.locals[name] }
	for _, p := range paths {
		base := g.pkgNames[p]
		name := base
		for i := 1; !free(name); i++ {
			name = base + strconv.Itoa(i)
		}
		taken[name] = true
		g.imports[p] = name
	}
}

func (g *fileGen) qualifier(p *types.Package) string {
	if p.Path() == g.target.Path() {
		return ""
	}
	return g.imports[p.Path()]
}

func (g *fileGen) typeString(t types.Type) string { return types.TypeString(t, g.qualifier) }

func (g *fileGen) writeImports(b *bytes.Buffer) {
	if len(g.imports) == 0 {
		return
	}
	var std, other []string
	for p := range g.imports {
		if first, _, _ := strings.Cut(p, "/"); strings.Contains(first, ".") {
			other = append(other, p)
		} else {
			std = append(std, p)
		}
	}
	sort.Strings(std)
	sort.Strings(other)

	b.WriteString("import (\n")
	for i, group := range [][]string{std, other} {
		if i > 0 && len(std) > 0 && len(other) > 0 {
			b.WriteString("\n")
		}
		for _, p := range group {
			if name := g.imports[p]; name != path.Base(p) {
				fmt.Fprintf(b, "\t%s %q\n", name, p)
			} else {
				fmt.Fprintf(b, "\t%q\n", p)
			}
		}
	}
	b.WriteString(")\n\n")
}

func (g *fileGen) writeFunc(b *bytes.Buffer, p *funcPlan) {
	inj := p.r.Injector
	sig := inj.Func.Signature()
	rootType := sig.Results().At(0).Type()

	params := make([]string, len(p.params))
	for i, name := range p.params {
		params[i] = name + " " + g.typeString(sig.Params().At(i).Type())
	}
	results := []string{g.typeString(rootType)}
	if inj.HasCleanup {
		results = append(results, "func()")
	}
	if inj.HasError {
		results = append(results, "error")
	}
	fmt.Fprintf(b, "func %s(%s) (%s) {\n", inj.FuncName, strings.Join(params, ", "), strings.Join(results, ", "))

	if p.useCleanup {
		fmt.Fprintf(b, "var %s []func()\n", p.cleanupArr)
		fmt.Fprintf(b, "%s := func() {\nfor i := len(%s) - 1; i >= 0; i-- {\n%s[i]()\n}\n}\n", p.cleanupFn, p.cleanupArr, p.cleanupArr)
	}

	var errReturn string
	if inj.HasError {
		ret := []string{zeroValue(rootType, g.qualifier)}
		if inj.HasCleanup {
			ret = append(ret, "nil")
		}
		errReturn = "return " + strings.Join(append(ret, p.errVar), ", ")
	}

	registered := false // whether a cleanup has been appended so far
	for i := range p.r.Steps {
		s := &p.r.Steps[i]
		lhs := []string{p.vars[i]}
		if s.Provider.HasCleanup {
			lhs = append(lhs, p.cleanups[i])
		}
		if s.Provider.HasError {
			lhs = append(lhs, p.errVar)
		}
		args := make([]string, len(s.Args))
		for j, a := range s.Args {
			args[j] = p.ref(a)
		}
		fn := s.Provider.FuncName
		if s.Provider.PkgPath != g.target.Path() {
			fn = g.imports[s.Provider.PkgPath] + "." + fn
		}
		fmt.Fprintf(b, "%s := %s(%s)\n", strings.Join(lhs, ", "), fn, strings.Join(args, ", "))

		if s.Provider.HasError {
			fmt.Fprintf(b, "if %s != nil {\n", p.errVar)
			if registered {
				fmt.Fprintf(b, "%s()\n", p.cleanupFn)
			}
			b.WriteString(errReturn + "\n}\n")
		}
		if s.Provider.HasCleanup {
			if p.useCleanup {
				fmt.Fprintf(b, "%s = append(%s, %s)\n", p.cleanupArr, p.cleanupArr, p.cleanups[i])
				registered = true
			} else {
				// Unreachable: the resolver rejects providers with cleanups
				// for injectors without one. Keep the variable used anyway.
				fmt.Fprintf(b, "_ = %s\n", p.cleanups[i])
			}
		}
	}

	ret := []string{p.ref(p.r.Root)}
	if inj.HasCleanup {
		if p.useCleanup {
			ret = append(ret, p.cleanupFn)
		} else {
			ret = append(ret, "func() {}")
		}
	}
	if inj.HasError {
		ret = append(ret, "nil")
	}
	fmt.Fprintf(b, "return %s\n}\n\n", strings.Join(ret, ", "))
}

// ref returns the local expression holding v.
func (p *funcPlan) ref(v ValueRef) string {
	if v.Kind == FromParam {
		return p.params[v.Index]
	}
	return p.vars[v.Index]
}

// zeroValue returns a Go expression for the zero value of t.
func zeroValue(t types.Type, q types.Qualifier) string {
	switch u := t.Underlying().(type) {
	case *types.Basic:
		switch {
		case u.Info()&types.IsBoolean != 0:
			return "false"
		case u.Info()&types.IsString != 0:
			return `""`
		case u.Info()&types.IsNumeric != 0:
			return "0"
		default:
			return "nil"
		}
	case *types.Pointer, *types.Interface, *types.Map, *types.Slice, *types.Chan, *types.Signature:
		return "nil"
	case *types.Struct, *types.Array:
		return types.TypeString(t, q) + "{}"
	default:
		return "*new(" + types.TypeString(t, q) + ")"
	}
}

// namer allocates unique local identifiers within one function.
type namer struct {
	reserved map[string]bool
	used     map[string]bool
	counters map[string]int
}

func newNamer(reserved map[string]bool) *namer {
	return &namer{reserved: reserved, used: make(map[string]bool), counters: make(map[string]int)}
}

func (n *namer) free(name string) bool {
	return !n.used[name] && !n.reserved[name] && !token.IsKeyword(name)
}

// take returns name, or name followed by the smallest numeric suffix that
// makes it unique.
func (n *namer) take(name string) string {
	cand := name
	for i := 1; !n.free(cand); i++ {
		cand = name + strconv.Itoa(i)
	}
	n.used[cand] = true
	return cand
}

// seq returns the next free identifier of the sequence prefix1, prefix2, ...
func (n *namer) seq(prefix string) string {
	for {
		n.counters[prefix]++
		cand := prefix + strconv.Itoa(n.counters[prefix])
		if n.free(cand) {
			n.used[cand] = true
			return cand
		}
	}
}
